mapper.select:
select alm.ai_llm_model_id as aiLlmModelId, alm.ai_llm_vendor_id as aiLlmVendorId, alv.vendor_name as vendorName, alm.model_name as modelName, alm.display_name as displayName, alm.builtin_status as builtinStatus, alm.enable_status as enableStatus, alm.thinking_capable as thinkingCapable, alm.thinking_default as thinkingDefault, alm.thinking_budget_tokens as thinkingBudgetTokens, alm.sort_num as sortNum, alm.remark as remark, alm.del_status as delStatus, alm.create_time as createTime, alm.update_time as updateTime from ai_llm_model alm left join ai_llm_vendor alv on alm.ai_llm_vendor_id = alv.ai_llm_vendor_id where alm.del_status = 0
and alm.ai_llm_vendor_id = #{aiLlmVendorId}
and alm.model_name like concat('%', #{modelName}, '%')
and alm.enable_status = #{enableStatus}
order by alm.sort_num asc, alm.ai_llm_model_id desc

select count(1)
from ai_llm_model alm
where alm.del_status = 0

    and alm.ai_llm_vendor_id = #{aiLlmVendorId}


    and alm.model_name like concat('%', #{modelName}, '%')


    and alm.enable_status = #{enableStatus}

select alm.ai_llm_model_id, alm.ai_llm_vendor_id, alm.model_name, alm.display_name, alm.builtin_status, alm.enable_status, alm.thinking_capable, alm.thinking_default, alm.thinking_budget_tokens, alm.sort_num, alm.remark, alm.del_status, alm.create_time, alm.update_time from ai_llm_model alm where alm.del_status = 0
and alm.ai_llm_vendor_id = #{aiLlmVendorId}
and alm.model_name like concat('%', #{modelName}, '%')
and alm.enable_status = #{enableStatus}
order by alm.ai_llm_model_id desc limit 1

mapper.update:
update ai_llm_model
set del_status = 1
where ai_llm_model_id = #{aiLlmModelId}
